import{_ as t,o,c as r,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"동시에 몇 개 돌릴까","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/concurrency"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/concurrency"}],["meta",{"property":"og:title","content":"동시에 몇 개 돌릴까"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/concurrency.md","filePath":"docs/concurrency.md"}'),c={name:"docs/concurrency.md"};function n(p,e,s,d,i,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="동시에-몇-개-돌릴까" tabindex="-1">동시에 몇 개 돌릴까 <a class="header-anchor" href="#동시에-몇-개-돌릴까" aria-label="Permalink to &quot;동시에 몇 개 돌릴까&quot;">​</a></h1><h2 id="동시성-설정값이-없는-이유" tabindex="-1">동시성 설정값이 없는 이유 <a class="header-anchor" href="#동시성-설정값이-없는-이유" aria-label="Permalink to &quot;동시성 설정값이 없는 이유&quot;">​</a></h2><p>&quot;동시 실행 3개까지&quot; 같은 칸을 찾고 계신다면 없습니다. <strong>동시에 도는 세션 수가 곧 워커 개수입니다.</strong> 워커가 하나면 큐에 티켓이 아무리 쌓여도 한 번에 한 세션이고, 둘이면 둘입니다.</p><p>늘리는 방법은 <a href="/docs/worker">워커</a> §<code>워커 생성</code> 한 번에 있습니다. 화면에서 누르면 끝납니다.</p><h2 id="워커-락-—-한-번에-티켓-1건" tabindex="-1">워커 락 — 한 번에 티켓 1건 <a class="header-anchor" href="#워커-락-—-한-번에-티켓-1건" aria-label="Permalink to &quot;워커 락 — 한 번에 티켓 1건&quot;">​</a></h2><p>워커는 동기 프로세스입니다. 한 번에 한 가지 일만 한다는 뜻이라, 잡은 티켓의 세션이 끝날 때까지 다음 티켓을 잡지 않습니다.</p><p>cron은 30초마다 그 워커를 부르지만, 앞 실행이 아직 세션을 쥐고 있으면 이번 호출은 그냥 넘어갑니다. 워커 락이 그 자리를 막기 때문입니다. 락은 &quot;이 워커는 지금 일하는 중&quot;이라고 걸어 두는 표시고, 덕분에 두 실행이 같은 티켓을 동시에 물 일도 한 워커가 세션 둘을 띄울 일도 없습니다.</p><p><code>w1</code>이 티켓 하나를 30분 물고 있어도 <code>w2</code>는 그동안 다른 티켓을 집습니다. 워커 여럿을 두는 값이 정확히 그것입니다.</p><p>세션이 무한정 붙잡는 것도 막혀 있습니다. 기본 5400초를 넘기면 세션을 끊고 티켓은 대기로 돌아갑니다. 그다음 호출에서 같은 워커든 다른 워커든 다시 집습니다. 그 값을 바꾸는 것은 <a href="/docs/ref-env">워커 환경변수</a>의 <code>TICKET_MAXRUN</code>입니다.</p><h2 id="토큰과-충돌-—-늘리면-같이-늘어나는-것" tabindex="-1">토큰과 충돌 — 늘리면 같이 늘어나는 것 <a class="header-anchor" href="#토큰과-충돌-—-늘리면-같이-늘어나는-것" aria-label="Permalink to &quot;토큰과 충돌 — 늘리면 같이 늘어나는 것&quot;">​</a></h2><p>워커를 늘리면 처리량만 늘어나지 않습니다.</p><ul><li><strong>토큰.</strong> 워커 다섯이 동시에 돌면 토큰도 다섯 배로 나갑니다. 한도는 머신·계정당 하나라 워커 전원이 그 한 통을 나눠 씁니다. 워커별 한도 같은 것은 세상에 없습니다. 지금 얼마나 썼고 얼마나 남았는지는 화면 맨 아래 토큰 status bar에 있습니다(<a href="/docs/screens">화면 소개</a> 참고).</li><li><strong>같은 파일을 동시에 건드릴 위험.</strong> 서로 다른 티켓이라도 같은 소스 파일이나 공유 dev DB를 같이 밟을 수 있습니다(동시 4세션이 컬럼을 드롭한 사례가 있습니다). 워커마다 git 워크트리가 따로인 것이 소스 쪽은 갈라 주지만, 데이터베이스나 외부 서비스는 갈라지지 않습니다. 엔진이 막지 않는 영역이고, 몇 개를 둘지는 그 위험을 알고 사람이 정합니다.</li></ul><p>둘부터 시작해서 대기 레인이 안 줄면 하나씩 늘리세요. 큐가 비어 있는데 워커만 다섯이면 아무 이득도 없이 cron만 다섯 배로 돕니다.</p><p>다음은 <a href="/docs/personas">페르소나</a>입니다.</p>',14)])])}const u=t(c,[["render",n]]);export{m as __pageData,u as default};
